enum integrity_status verify_hmac_xattr(struct dentry *dentry,
                                        const char *xattr_name,
                                        char *xattr_value,
                                        size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status;
    void *digest = NULL;
    size_t digest_len = 0;
    int rc;

    if (iint->flags & INTEGRITY_IINT_HMAC_VERIFIED)
        return iint->status;

    rc = get_xattr_digest(dentry, xattr_name, &digest, &digest_len);
    if (rc < 0) {
        if (rc == -ENODATA)
            status = INTEGRITY_NO_DIGEST;
        else
            status = INTEGRITY_DIGEST_ERROR;
        goto out;
    }

    if (digest_len != xattr_value_len) {
        status = INTEGRITY_DIGEST_MISMATCH;
        goto out_free;
    }

    rc = crypto_hmac_compare(digest, xattr_value, xattr_value_len);
    if (rc) {
        status = INTEGRITY_DIGEST_MISMATCH;
        goto out_free;
    }

    status = INTEGRITY_DIGEST_OK;

out_free:
    kfree(digest);
out:
    iint->status = status;
    iint->flags |= INTEGRITY_IINT_HMAC_VERIFIED;
    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status;
    void *digest;
    size_t digest_len = 0;
    int rc;

    if (!xattr_name || !xattr_value || !iint)
        return INTEGRITY_NOLIB;

    status = iint->flags & INTEGRITY_SIGNATURE_DIGEST_PRESENT ? INTEGRITY_PASS : INTEGRITY_NOLIB;

    digest = kmalloc(xattr_value_len, GFP_KERNEL);
    if (!digest)
        return INTEGRITY_FAIL;

    rc = security_getxattr(dentry, xattr_name, digest, xattr_value_len, 0);
    if (rc < 0) {
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    digest_len = rc;

    if (digest_len != xattr_value_len) {
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    if (memcmp(digest, xattr_value, digest_len) != 0)
        status = INTEGRITY_FAIL;
    else
        status = INTEGRITY_PASS;

    kfree(digest);

    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status;
    void *digest;
    size_t digest_len;
    int result;

    if (iint->flags & INTEGRITY_SIGNATURE_PRESENT)
        return INTEGRITY_STATUS_NO_CHANGE;

    digest = get_xattr_digest(dentry, xattr_name, &digest_len);
    if (!digest)
        return INTEGRITY_STATUS_NO_ATTRIBUTE;

    switch (xattr_name[0]) {
    case HMAC_TYPE_SHA256:
        result = verify_hmac_sha256(dentry, xattr_value, xattr_value_len, digest, digest_len);
        break;
    case HMAC_TYPE_SHA1:
        result = verify_hmac_sha1(dentry, xattr_value, xattr_value_len, digest, digest_len);
        break;
    default:
        result = -EINVAL;
        break;
    }

    kfree(digest);

    if (result < 0) {
        iint->flags |= INTEGRITY_SIGNATURE_INVALID;
        return INTEGRITY_STATUS_FAILURE;
    }

    return INTEGRITY_STATUS_SUCCESS;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status = INTEGRITY_PASS;
    void *digest = NULL;
    size_t digest_len = 0;
    int result;

    if (iint->flags & INTEGRITY_SIGNATURE_PRESENT)
        return status;

    result = get_xattr_data(dentry, xattr_name, &digest, &digest_len);
    if (result < 0) {
        if (result == -ENODATA)
            status = INTEGRITY_NOLABEL;
        else
            status = INTEGRITY_FAIL;
        return status;
    }

    if (digest_len == 0) {
        kfree(digest);
        return INTEGRITY_NOLABEL;
    }

    result = verify_hmac(dentry, digest, digest_len, xattr_value, xattr_value_len);
    if (result != 0)
        status = INTEGRITY_FAIL;

    kfree(digest);
    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint) {
    enum integrity_status status = INTEGRITY_PASS;
    void *digest = NULL;
    size_t digest_len = 0;
    int result;

    if (!xattr_name || !xattr_value || !iint)
        return INTEGRITY_NO_ATTRIBUTE;

    if (iint->flags & INTEGRITY_HMAC_PRESENT)
        return iint->status;

    result = get_xattr_digest(dentry, xattr_name, &digest, &digest_len);
    if (result < 0) {
        status = INTEGRITY_NO_ATTRIBUTE;
        goto out;
    }

    if (digest_len != xattr_value_len || memcmp(digest, xattr_value, digest_len) != 0) {
        status = INTEGRITY_FAIL;
        goto out;
    }

out:
    kfree(digest);
    iint->status = status;
    iint->flags |= INTEGRITY_HMAC_PRESENT;
    return status;
}
